syntax:
In a class definition, unqualified names are looked up as follows:

class Base {
    int member;  // Declared in Base scope
};

class Derived : public Base {
    int method() { return member; }  // 'member' is looked up in Derived's scope, then Base's scope
    // Implementation note: Compiler checks Derived first, then Base per 10.2 of the standard.
};

code_example:
#include <iostream>
namespace Outer {
    class Base {
        public:
            int value = 10;  // Member of Base
    };

    class Derived : public Base {
        public:
            int getValue() {
                return value;  // 'value' is an unqualified name; compiler looks in Derived, then Base
            }
    };

    int main() {
        Derived d;
        std::cout << d.getValue() << std::endl;  // Outputs 10
        return 0;
    }
}
